<template>
  <div class="page-container ops-workspace">
    <div class="page-header"><div class="page-header-title"><h1>{{ title }}</h1><p>可追踪发布 · 受控恢复 · 保留原有监控</p></div><button class="btn btn-secondary" :disabled="loading" @click="refresh">刷新</button></div>
    <div v-if="error" role="alert" class="ops-error">{{ error }}</div>
    <div v-if="section === 'overview'">
      <div class="ops-metrics"><article v-for="item in [{ label: '服务器', value: overview.hosts }, { label: '运行容器', value: overview.running }, { label: '异常容器', value: overview.abnormal }, { label: '部署版本', value: overview.versions }, { label: '未恢复告警', value: overview.alerts }]" :key="item.label"><small>{{ item.label }}</small><strong>{{ item.value }}</strong></article></div>
      <section class="ops-panel"><h2>运行时与资源</h2><div class="ops-grid"><article v-for="s in state.snapshot" :key="s.id" class="ops-runtime"><h3>{{ s.host_id }} <span class="ops-badge" :class="{ warning: age(s.observed_at) }">{{ age(s.observed_at) ? '数据过期 / 请检查连接' : '已连接' }}</span></h3><p>Docker {{ s.data?.docker_version }} · {{ s.data?.cpu_count }} CPU · {{ Math.round((s.data?.memory_bytes || 0) / 1024 / 1024) }} MiB</p><p>最近采集 {{ time(s.observed_at) }}</p><div v-for="r in s.data?.resources || []" :key="r.ID">{{ r.Name }}：CPU {{ r.CPUPerc }} / 内存 {{ r.MemPerc }}</div></article></div><p v-if="!state.snapshot.length" class="ops-empty">注册服务器并执行连接检测后显示真实采集数据。</p></section>
      <section class="ops-panel"><h2>最近部署</h2><div v-for="version in state.version.slice(0, 6)" :key="version.id" class="ops-record"><strong>{{ version.app_id }}</strong><code>{{ version.spec?.image }}</code><span>{{ time(version.created_at) }}</span></div><p v-if="!state.version.length" class="ops-empty">暂无成功部署记录</p></section>
      <router-link to="/dashboard">进入原有监控首页 →</router-link>
    </div>

    <template v-if="section === 'servers'">
      <form v-if="capabilities.administrator" class="ops-panel ops-form" @submit.prevent="save('host', { ...hostDraft, monitor_host_id: Number(hostDraft.monitor_host_id) })">
        <h2>注册受管服务器</h2><p>复用主机维护中的加密凭据；先独立安装受控代理并核实 SSH 主机公钥。</p>
        <div class="ops-grid"><label>服务器标识<input v-model="hostDraft.id" required maxlength="64" :readonly="!!hostDraft.revision"></label><label>显示名称<input v-model="hostDraft.name" required></label><label>监控主机<select v-model="hostDraft.monitor_host_id" required><option value="">选择已有主机</option><option v-for="h in monitorHosts" :key="h.id" :value="h.id">{{ h.host_name }} · {{ h.ip }}</option></select></label><label>环境<input v-model="hostDraft.environment" required placeholder="由实际部署环境定义"></label><label>分组<input v-model="hostDraft.group"></label><label class="ops-wide">SSH 主机公钥<input v-model="hostDraft.ssh_host_key" required placeholder="ssh-ed25519 AAAA...（通过可信渠道核验）"></label></div><button class="btn btn-primary" :disabled="busy">{{ hostDraft.revision ? "保存服务器" : "注册服务器" }}</button><button type="button" @click="resetDraft(hostDraft)">新建服务器</button>
      </form>
      <section class="ops-panel"><h2>服务器列表</h2><div class="ops-table-wrap"><table><thead><tr><th>服务器</th><th>环境 / 分组</th><th>维护状态</th><th>运行时</th><th>操作</th></tr></thead><tbody><tr v-for="h in state.host" :key="h.id"><td>{{ h.name || h.id }}<small>{{ h.id }}</small></td><td>{{ h.environment }} / {{ h.group || '—' }}</td><td>{{ h.maintenance ? '维护中' : '正常' }}</td><td>{{ state.snapshot.find(s => s.id === h.id)?.data?.docker_version || '尚未连接' }}</td><td><button v-if="capabilities.administrator" @click="Object.assign(hostDraft, h)">编辑</button><button :disabled="busy || !permitted(h.id, 'probe')" @click="operate('probe', h)">连接检测</button><button :disabled="busy || !permitted(h.id, h.maintenance ? 'maintenance_off' : 'maintenance_on')" @click="operate(h.maintenance ? 'maintenance_off' : 'maintenance_on', h)">{{ h.maintenance ? '结束维护' : '进入维护' }}</button></td></tr></tbody></table></div></section>
    </template>

    <template v-if="section === 'images'">
      <form v-if="capabilities.administrator" class="ops-panel ops-form" @submit.prevent="save('registry', registryDraft)"><h2>批准镜像仓库</h2><div class="ops-grid"><label>仓库标识<input v-model="registryDraft.id" required :readonly="!!registryDraft.revision"></label><label>名称<input v-model="registryDraft.name" required></label><label>域名与端口<input v-model="registryDraft.address" required placeholder="registry.example.com:5000"></label><label>凭据引用<input v-model="registryDraft.credential_ref" placeholder="代理 Secret 目录下的 Docker 配置目录名"></label></div><button class="btn btn-primary" :disabled="busy">保存仓库</button><button type="button" @click="resetDraft(registryDraft)">新建仓库</button></form>
      <section class="ops-panel"><h2>已配置仓库</h2><div v-for="r in state.registry" :key="r.id" class="ops-record"><strong>{{ r.name }}</strong><code>{{ r.address }}</code><span>凭据：{{ r.credential_ref || '匿名拉取' }}</span><button v-if="capabilities.administrator" @click="Object.assign(registryDraft, r)">编辑</button></div></section>
      <section class="ops-panel ops-form"><h2>远程仓库版本查询</h2><div class="ops-grid"><label>执行服务器<select v-model="imageDraft.host_id"><option value="">选择服务器</option><option v-for="h in state.host" :key="h.id" :value="h.id">{{ h.name || h.id }}</option></select></label><label>仓库<select v-model="imageDraft.registry_id"><option value="">选择仓库</option><option v-for="r in state.registry" :key="r.id" :value="r.id">{{ r.address }}</option></select></label><label>镜像仓库路径<input v-model="imageDraft.repository" placeholder="支持 V2 catalog，或直接填写 repository"></label><label>Tag<input v-model="imageDraft.tag" placeholder="解析为不可变 Digest 后发布"></label></div><div class="ops-actions"><button :disabled="busy || !imageDraft.registry_id || !permitted(imageDraft.host_id, 'registry_catalog')" @click="imageOperation('registry_catalog')">查询仓库 / Tags</button><button :disabled="busy || !imageDraft.registry_id || !imageDraft.repository || !imageDraft.tag || !permitted(imageDraft.host_id, 'resolve_image')" @click="imageOperation('resolve_image')">解析版本 Digest</button></div><p>部分公共仓库不开放 catalog，可填写镜像路径查询 Tags。每页最多 100 项。</p><pre v-if="registryResults">{{ pretty(registryResults) }}</pre></section>
      <form class="ops-panel ops-form" @submit.prevent="imageOperation('pull')"><h2>主机镜像与版本</h2><div class="ops-grid"><label>目标服务器<select v-model="imageDraft.host_id" required><option value="">选择服务器</option><option v-for="h in state.host" :key="h.id" :value="h.id">{{ h.name || h.id }} / {{ h.environment }}</option></select></label><label class="ops-wide">不可变镜像地址<input v-model="imageDraft.image" placeholder="registry/repository@sha256:..." required></label></div><div class="ops-actions"><button class="btn btn-primary" :disabled="busy || !permitted(imageDraft.host_id, 'pull')">拉取指定 Digest</button><button type="button" :disabled="busy || !permitted(imageDraft.host_id, 'images')" @click="imageOperation('images')">查看本机镜像</button><button type="button" :disabled="busy || !permitted(imageDraft.host_id, 'cleanup')" @click="imageOperation('cleanup')">清理未使用镜像</button></div><p>清理不会强制删除，也不会批量 prune；仍被容器引用的镜像由 Docker 拒绝删除。</p><pre v-if="imageResults.length">{{ pretty(imageResults) }}</pre></form>
    </template>

    <template v-if="section === 'deployments'">
      <form class="ops-panel ops-form" @submit.prevent="saveApp"><h2>{{ appDraft.revision ? '编辑部署配置' : '创建部署配置' }}</h2><div class="ops-grid">
        <label>应用标识<input v-model="appDraft.id" required :readonly="!!appDraft.revision"></label><label>应用名称<input v-model="appDraft.name" required></label>
        <label>目标服务器<select v-model="appDraft.host_id" required :disabled="!!appDraft.revision" @change="selectHost"><option value="">选择服务器</option><option v-for="h in state.host" :key="h.id" :value="h.id">{{ h.name || h.id }} / {{ h.environment }}</option></select></label><label>部署环境<input v-model="appDraft.environment" readonly required></label>
        <label class="ops-wide">镜像地址与 Digest<input v-model="appDraft.image" required placeholder="registry/repository@sha256:..."></label>
        <label class="ops-wide">容器启动参数（JSON argv，空数组使用镜像默认值）<input v-model="editor.command" required></label>
        <label>CPU 核数<input v-model.number="appDraft.cpus" type="number" min="0.1" step="0.1" required></label><label>内存上限 MiB<input v-model.number="appDraft.memory_mb" type="number" min="16" required></label>
        <label>Docker 网络<input v-model="appDraft.network" required></label><label>数据类型<select v-model="appDraft.data_kind"><option v-for="kind in capabilities.data_kinds" :key="kind">{{ kind }}</option></select></label>
        <label>容器运行用户<input v-model="appDraft.user" placeholder="留空沿用镜像 USER；可填写 UID:GID"></label>
        <label>重启策略<select v-model="appDraft.restart_policy"><option v-for="p in capabilities.restart_policies" :key="p">{{ p }}</option></select></label><label>重启上限<input v-model.number="appDraft.restart_limit" type="number" min="1" max="20" required></label>
        <label>普通环境变量<textarea v-model="editor.env" placeholder="NAME=value，一行一项"></textarea></label><label>Secret 引用<textarea v-model="editor.secrets" placeholder="ENV_NAME=agent-local-file，仅填写引用"></textarea></label>
        <label class="ops-wide">健康检查命令（JSON argv）<input v-model="editor.health" required placeholder='["executable", "argument"]'></label>
        <label>检测间隔（秒）<input v-model.number="appDraft.health.interval_seconds" type="number" min="1" required></label><label>检测超时（秒）<input v-model.number="appDraft.health.timeout_seconds" type="number" min="1" required></label>
        <label>发布健康等待（秒）<input v-model.number="appDraft.health_deadline_seconds" type="number" min="5" max="600" required></label><label>持续故障判定（秒）<input v-model.number="appDraft.failure_window_seconds" type="number" min="1" required></label>
        <label><span>独立恢复持续 unhealthy</span><input v-model="appDraft.recover_unhealthy" type="checkbox"></label>
        <label>备份周期（小时，0 为手动）<input v-model.number="appDraft.backup_interval_hours" type="number" min="0"></label><label>备份保留周期（天）<input v-model.number="appDraft.backup_retention_days" type="number" min="1"></label>
        <template v-if="appDraft.data_kind === 'postgres'"><label>PostgreSQL 数据库<input v-model="appDraft.postgres_database" required></label><label>数据库用户<input v-model="appDraft.postgres_user" required></label></template>
      </div>
      <fieldset><legend>端口映射</legend><div v-for="(p, i) in appDraft.ports" :key="i" class="ops-row"><label>主机端口<input v-model.number="p.host" type="number" required></label><label>容器端口<input v-model.number="p.container" type="number" required></label><label>协议<select v-model="p.protocol"><option>tcp</option><option>udp</option></select></label><button type="button" @click="appDraft.ports.splice(i, 1)">移除</button></div><button type="button" @click="appDraft.ports.push({ host: null, container: null, protocol: 'tcp' })">添加端口</button></fieldset>
      <fieldset><legend>持久卷与配置挂载</legend><div v-for="(m, i) in appDraft.mounts" :key="i" class="ops-row"><label>类型<select v-model="m.type"><option value="volume">命名卷</option><option value="bind">只读配置目录</option></select></label><label>源<input v-model="m.source" required placeholder="lm- 卷名 / 白名单目录"></label><label>容器路径<input v-model="m.target" required></label><label>只读<input v-model="m.read_only" type="checkbox"></label><button type="button" @click="appDraft.mounts.splice(i, 1)">移除</button></div><button type="button" @click="appDraft.mounts.push({ type: 'volume', source: '', target: '', read_only: false })">添加挂载</button></fieldset>
      <div class="ops-actions"><button class="btn btn-primary" :disabled="busy || !permitted(appDraft.host_id, 'deploy')">保存部署配置</button><button type="button" @click="resetApp">新建 / 重置表单</button></div></form>
      <section class="ops-panel"><h2>应用与发布</h2><article v-for="app in state.application" :key="app.id" class="ops-app"><div><h3>{{ app.name || app.id }} <span class="ops-badge">{{ app.environment }}</span></h3><code>{{ app.image }}</code><p>目标 {{ app.host_id }} · 期望状态 {{ app.desired_state }} · 当前版本 {{ app.active_version || '尚未部署' }}</p></div><div class="ops-actions"><button @click="editApp(app)">编辑配置</button><button :disabled="busy || !permitted(app.host_id, 'validate')" @click="operate('validate', app)">发布前校验</button><button class="btn btn-primary" :disabled="busy || !permitted(app.host_id, 'deploy')" @click="deploy(app)">确认发布 / 升级</button></div><details><summary>版本历史与受控回滚</summary><div v-for="v in state.version.filter(v => v.app_id === app.id)" :key="v.id" class="ops-record"><code>{{ v.spec?.image }}</code><span>{{ time(v.created_at) }}</span><button :disabled="busy || !permitted(app.host_id, 'rollback')" @click="deploy(app, 'rollback', { version_id: v.id })">回滚到此版本</button></div></details></article></section>
    </template>

    <section v-if="section === 'containers'" class="ops-panel"><h2>受管容器</h2><p>人工停机不触发恢复；进程异常退出优先由 Docker 策略处理，持续健康检查失败按独立策略恢复。</p><div class="ops-table-wrap"><table><thead><tr><th>容器 / 应用</th><th>服务器</th><th>运行 / 健康状态</th><th>人工停机</th><th>恢复尝试</th><th>操作</th></tr></thead><tbody><tr v-for="c in containers" :key="c.host_id + c.name"><td>{{ c.name }}<small>{{ c.app_id }}</small></td><td>{{ c.host_id }}<small>{{ age(c.observed_at) ? '采集已过期' : time(c.observed_at) }}</small></td><td>{{ c.status }} / {{ c.health }}</td><td>{{ c.manual_stop ? '是' : '否' }}</td><td>{{ c.recovery_attempts }} / 原生 {{ c.native_restarts }}</td><td><button v-for="action in ['start', 'stop', 'restart', 'logs']" :key="action" :disabled="busy || !permitted(c.host_id, action)" @click="operate(action, state.application.find(a => a.id === c.app_id))">{{ { start: '启动', stop: '停止', restart: '重启', logs: '刷新日志' }[action] }}</button></td></tr></tbody></table></div><p v-if="!containers.length" class="ops-empty">暂无受管容器。部署成功并完成状态采集后显示。</p></section>

    <template v-if="section === 'backups'"><section class="ops-panel"><h2>创建备份</h2><p>命名卷要求所有写入容器已停止；PostgreSQL 使用逻辑备份。配置只备份 Secret 引用。恢复始终创建新目标，保留原数据。</p><div v-for="app in state.application" :key="app.id" class="ops-record"><strong>{{ app.name || app.id }}</strong><span>{{ app.data_kind }}</span><button :disabled="busy || !permitted(app.host_id, 'backup')" @click="operate('backup', app)">执行备份</button></div></section><section class="ops-panel"><h2>备份记录</h2><div v-for="backup in state.backup" :key="backup.id" class="ops-app"><strong>{{ backup.app_id }} · {{ backup.kind }}</strong><p>{{ time(backup.created_at) }} · 校验 {{ backup.verified ? '通过' : '未通过' }} · 恢复演练 {{ backup.restore_tested ? '通过' : '未验证' }} · 保留 {{ backup.retention_days }} 天（到期不自动删除）</p><div class="ops-actions"><button :disabled="busy || !permitted(backup.host_id, 'restore_test')" @click="backupOperation('restore_test', backup)">恢复到隔离目标并校验</button><button :disabled="busy || !backup.restore_tested || !permitted(backup.host_id, 'restore')" @click="backupOperation('restore', backup)">恢复到新卷 / 新数据库</button></div></div></section></template>

    <section v-if="section === 'alerts'" class="ops-panel"><h2>异常、熔断与恢复事件</h2><div v-for="a in state.alert" :key="a.id" class="ops-record"><span class="ops-badge" :class="{ warning: a.status === 'OPEN' }">{{ a.severity }}</span><strong>{{ a.app_id }}</strong><span>{{ a.code }} · {{ a.status }}</span><span>{{ time(a.created_at) }}<br>{{ a.recovered_at ? '恢复 ' + time(a.recovered_at) : '' }}</span><button :disabled="busy || !!a.acknowledged_by || !permitted(a.host_id, 'ack')" @click="acknowledge(a.id)">{{ a.acknowledged_by ? '已确认：' + a.acknowledged_by : '确认告警' }}</button></div><p v-if="!state.alert.length" class="ops-empty">暂无运维告警</p></section>

    <section v-if="section === 'permissions'" class="ops-panel ops-form"><h2>运维角色与资源授权</h2><p v-if="!capabilities.administrator">仅管理员可以配置运维授权。嵌入页面身份不能进行运维操作。</p><template v-else><form @submit.prevent="save('grant', grantDraft)"><div class="ops-grid"><label>授权标识<input v-model="grantDraft.id" required></label><label>用户 ID<input v-model="grantDraft.user_id" :readonly="state.grant.some(g => g.id === grantDraft.id)" required></label><label>服务器范围<select v-model="grantDraft.host_id"><option value="*">全部服务器</option><option v-for="h in state.host" :key="h.id" :value="h.id">{{ h.name || h.id }}</option></select></label><label>环境范围<input v-model="grantDraft.environment" required></label><label>角色<select v-model="grantDraft.role" required @change="roleChanged"><option value="">选择角色</option><option v-for="role in Object.keys(capabilities.roles)" :key="role">{{ role }}</option></select></label><label>允许操作（逗号分隔，可细化）<input v-model="grantDraft.actions" required></label><label>限定为运维账号（关闭旧监控接口）<input v-model="grantDraft.ops_only" type="checkbox"></label><label>启用此授权<input v-model="grantDraft.enabled" type="checkbox"></label></div><button class="btn btn-primary" :disabled="busy">保存授权</button></form><div v-for="g in state.grant" :key="g.id" class="ops-record"><strong>{{ g.user_id }}{{ g.enabled === false ? "（已撤销）" : "" }}</strong><span>{{ g.host_id }} / {{ g.environment }}</span><code>{{ g.actions }}</code><button @click="Object.assign(grantDraft, g, { ops_only: !!g.ops_only })">编辑</button></div></template></section>

    <form v-if="section === 'alerts' && capabilities.administrator" class="ops-panel ops-form" @submit.prevent="save('alert_rule', alertRuleDraft)"><h2>告警规则</h2><p>具体应用、具体事件的规则优先。停用规则抑制后续通知记录，不改变容器恢复策略或删除既有事件。</p><div class="ops-grid"><label>规则标识<input v-model="alertRuleDraft.id" required :readonly="!!alertRuleDraft.revision"></label><label>服务器<select v-model="alertRuleDraft.host_id" required><option value="">选择服务器</option><option v-for="h in state.host" :key="h.id" :value="h.id">{{ h.name || h.id }}</option></select></label><label>应用范围<select v-model="alertRuleDraft.app_id"><option value="">主机内全部应用</option><option v-for="a in state.application.filter(a => a.host_id === alertRuleDraft.host_id)" :key="a.id" :value="a.id">{{ a.name || a.id }}</option></select></label><label>事件类型<select v-model="alertRuleDraft.code"><option v-for="code in capabilities.event_codes" :key="code">{{ code }}</option></select></label><label>告警等级<select v-model="alertRuleDraft.severity"><option>WARNING</option><option>ERROR</option><option>CRITICAL</option></select></label><label>启用规则<input v-model="alertRuleDraft.enabled" type="checkbox"></label></div><button class="btn btn-primary" :disabled="busy">保存规则</button><div v-for="r in state.alert_rule" :key="r.id" class="ops-record"><strong>{{ r.id }}</strong><span>{{ r.host_id }} / {{ r.app_id || '全部应用' }} / {{ r.code }}</span><span>{{ r.severity }} · {{ r.enabled ? '启用' : '抑制' }}</span><button type="button" @click="Object.assign(alertRuleDraft, r)">编辑</button></div></form>
    <section v-if="section === 'containers'" class="ops-panel"><h2>实时日志</h2><div class="ops-actions"><button v-for="app in state.application" :key="app.id" :disabled="!permitted(app.host_id, 'logs')" @click="startLiveLogs(app)">{{ app.name || app.id }}</button><button v-if="liveLogApp" @click="stopLiveLogs">停止跟踪</button></div><p>按任务串行拉取最近 100 行；上一个请求结束后再拉取，不积压任务。{{ liveLogApp ? liveLogApp.id : '请选择应用' }} · {{ liveLogTime ? '更新于 ' + time(liveLogTime) : '尚未读取' }}</p><pre v-if="liveLogApp">{{ liveLogs || '等待日志…' }}</pre></section>
    <section class="ops-panel" v-if="activeTask"><div class="ops-task-head"><h2>当前任务 · {{ activeTask.action }}</h2><span class="ops-badge">{{ activeTask.status }}</span></div><progress :value="activeTask.progress" max="100"></progress><p>{{ activeTask.message }} · {{ activeTask.progress }}%</p><small>{{ activeTask.id }}</small><ol class="ops-events"><li v-for="(event, i) in activeTask.events || []" :key="i">{{ time(event.created_at) }} · {{ event.message }} · {{ event.progress }}%</li></ol><pre v-if="activeTask.result_json && activeTask.result_json !== '{}'">{{ pretty(JSON.parse(activeTask.result_json)) }}</pre></section>
    <section class="ops-panel" v-if="section === 'tasks' || section === 'overview'"><h2>任务历史</h2><div class="ops-table-wrap"><table><thead><tr><th>操作</th><th>资源 / 服务器</th><th>状态与进度</th><th>结果</th><th>时间</th></tr></thead><tbody><tr v-for="task in tasks.slice(0, section === 'overview' ? 6 : 200)" :key="task.id" @click="follow(task)" class="ops-clickable"><td>{{ task.action }}</td><td>{{ task.resource_id }} / {{ task.host_id }}</td><td>{{ task.status }} · {{ task.progress }}%</td><td>{{ task.message }}</td><td>{{ time(task.created_at) }}</td></tr></tbody></table></div></section>
    <section v-if="section === 'tasks' && capabilities.administrator" class="ops-panel"><h2>操作审计</h2><div v-for="a in audit" :key="a.id" class="ops-record"><span>{{ time(a.created_at) }}</span><strong>{{ a.actor }}</strong><span>{{ a.action }} / {{ a.resource_id }}</span><span>{{ a.outcome }}</span><small>{{ a.task_id }}</small></div></section>
  </div>
</template>
<script setup>
import { useRoute } from 'vue-router'
import { useOpsPlatform } from '../ops/useOpsPlatform'
